using Npgsql;
namespace BmsDesktop.Infrastructure;
public sealed class MigrationRunner { private readonly Database _db; public MigrationRunner(Database db)=>_db=db; public async Task ApplyFolderAsync(string folder){if(!Directory.Exists(folder))throw new DirectoryNotFoundException(folder);await using var cn=await _db.OpenAsync();await using(var init=new NpgsqlCommand("create table if not exists schema_migrations(version varchar(80) primary key,applied_at timestamptz not null default now())",cn))await init.ExecuteNonQueryAsync();foreach(var file in Directory.GetFiles(folder,"*.sql").OrderBy(Path.GetFileName)){var version=Path.GetFileName(file);await using var exists=new NpgsqlCommand("select exists(select 1 from schema_migrations where version=@v)",cn);exists.Parameters.AddWithValue("v",version);if(Convert.ToBoolean(await exists.ExecuteScalarAsync()))continue;var sql=await File.ReadAllTextAsync(file);await using var tx=await cn.BeginTransactionAsync();try{await using(var run=new NpgsqlCommand(sql,cn,tx)){run.CommandTimeout=120;await run.ExecuteNonQueryAsync();}await using(var mark=new NpgsqlCommand("insert into schema_migrations(version) values(@v)",cn,tx)){mark.Parameters.AddWithValue("v",version);await mark.ExecuteNonQueryAsync();}await tx.CommitAsync();}catch{await tx.RollbackAsync();throw;}}} }
